#        2 usage / payload unreadable (could-not-observe, distinct from "missing")
set -euo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PAYLOAD="$HERE/../../setup/references/operator-permissions.json"
PROJECT_DIR="${1:-$PWD}"
JSON_OUT=0
for a in "$@"; do [ "$a" = "--json" ] && JSON_OUT=1; done
[ -f "$PAYLOAD" ] || { echo "ERROR: payload not found at $PAYLOAD"; exit 2; }

HOME_DIR="${ORK_SETTINGS_HOME:-$HOME}"
node "$HERE/check-operator-permissions.cjs" "$PAYLOAD" "$PROJECT_DIR" "$HOME_DIR" "$JSON_OUT"
